import assert from "node:assert/strict";
import type { Page } from "@playwright/test";
import type { MutationGate } from "./w02-mutation";
import { uuid } from "../../src/contracts/common";
import { distribution } from "./w01-capture";
import { deadline } from "./w01-runtime";
import { proofErrors } from "./p07-proof-errors";
export type CurrentExpected={projectId:string;workflowId:string;revisionId:string;nodeId:string;scenario:number;index:number;context:number;view:"graph"|"list";fact:"readiness"|"review";origin:string|null;taskId:string;version:number|null;workRevision:number|null;reworkRound:number|null;artifactRef:string|null;ready:boolean|null;decision:string|null;eventId:string|null};
export type CurrentCapture=CurrentExpected & {elapsedMs:number;frames:number;matched:number;exact:boolean;visible:boolean;hitTest:boolean;observed?:Record<string,string|undefined>[]};
export type VisibilityReceipt={scenario:number;expected:CurrentExpected[];captures:CurrentCapture[];originals:unknown[];failures:unknown[];summary?:unknown;rows?:unknown[]};
export function declareVisibility(plan:Pick<CurrentExpected,"projectId"|"workflowId"|"revisionId"|"nodeId"|"taskId">,transitions=10):VisibilityReceipt[]{
 return [1,2,3].map(scenario=>({scenario,expected:Array.from({length:transitions},(_,index)=>[0,1].map(context=>({...plan,scenario,index,context,view:context===0?"graph" as const:"list" as const,fact:scenario===1?"readiness" as const:"review" as const,origin:null,version:null,workRevision:null,reworkRound:null,artifactRef:null,ready:null,decision:null,eventId:null}))).flat(),captures:[],originals:[],failures:[]}));
}
export function summarizeCurrent(expected:CurrentExpected[],captures:CurrentCapture[]){
 const key=(x:CurrentExpected)=>`${x.scenario}:${x.index}:${x.context}`,wanted=new Map(expected.map(e=>[key(e),e]));assert.equal(wanted.size,expected.length,"duplicate expected identities");const seen=new Map<string,number>(),present=new Set<string>(),confirmed=new Set<string>();let wrong=0,hidden=0,late=0;
 for(const c of captures){const k=key(c),e=wanted.get(k);seen.set(k,(seen.get(k)??0)+1);const bound=!!e&&e.origin!==null&&Object.keys(e).every(field=>e[field as keyof CurrentExpected]===c[field as keyof CurrentExpected]);if(bound&&c.matched>0)present.add(k);if(!bound||!c.exact)wrong++;if(!c.visible||!c.hitTest)hidden++;if(!Number.isFinite(c.elapsedMs)||c.elapsedMs>=2000)late++;if(bound&&c.exact&&c.visible&&c.hitTest&&c.frames===2&&c.matched===1&&Number.isFinite(c.elapsedMs)&&c.elapsedMs>=0)confirmed.add(k);}
 const missing=expected.length-present.size,unconfirmed=expected.length-confirmed.size,notRun=expected.filter(e=>e.origin===null).length,duplicate=[...seen.values()].reduce((n,c)=>n+Math.max(0,c-1),0)+captures.reduce((n,c)=>n+Math.max(0,c.matched-1),0);
 return {expected:expected.length,captured:captures.length,notRun,missing,unconfirmed,duplicate,wrong,hidden,late,valid:!missing&&!unconfirmed&&!duplicate&&!wrong&&!hidden&&!late,distribution:captures.length&&captures.every(c=>Number.isFinite(c.elapsedMs)&&c.elapsedMs>=0)?distribution(captures.map(c=>c.elapsedMs)):null};
}
export function visibilitySummary(receipts:VisibilityReceipt[]){return {overall:summarizeCurrent(receipts.flatMap(r=>r.expected),receipts.flatMap(r=>r.captures)),scenarios:receipts.map(r=>({scenario:r.scenario,summary:summarizeCurrent(r.expected,r.captures),views:(["graph","list"] as const).map(view=>({view,summary:summarizeCurrent(r.expected.filter(e=>e.view===view),r.captures.filter(c=>c.view===view))}))}))};}
export function summarizeSamples(expected:{id:string;warmup:boolean}[],samples:{id:string;warmup:boolean;elapsedMs:number|null;status:number|null}[]){
 assert.equal(new Set(expected.map(e=>e.id)).size,expected.length);assert.equal(samples.length,expected.length,"all original warm and measured samples required");assert.equal(new Set(samples.map(e=>e.id)).size,samples.length);for(const e of expected){const s=samples.find(s=>s.id===e.id);assert(s&&s.warmup===e.warmup&&typeof s.status==="number"&&s.status>=200&&s.status<300&&typeof s.elapsedMs==="number"&&Number.isFinite(s.elapsedMs)&&s.elapsedMs>=0,"missing/failed/nonfinite sample");}return distribution(samples.filter(s=>!s.warmup).map(s=>{assert(s.elapsedMs!==null);return s.elapsedMs;}));
}
export function validateReceiptBody(stored:unknown,wire:unknown,minimal:boolean,project:(body:unknown)=>unknown){const expected=minimal?project(stored):stored;assert.deepEqual(expected,wire,"original receipt/selected wire representation mismatch");return minimal?expected:undefined;}
export function validateGeneration(header:string|null,body:{generation?:unknown}){uuid.parse(header);assert.equal(header,body.generation,"original generation header/envelope mismatch");return header!;}
export function validateCliClock(c:{code:number|null;dispatchMs:number;exitMs:number|null;drainedMs:number;timedOut:boolean;forcedDrain:boolean}){assert.equal(c.code,0);assert(!c.timedOut&&!c.forcedDrain&&c.exitMs!==null);assert(c.exitMs>=c.dispatchMs&&c.drainedMs>=c.exitMs);assert(c.exitMs-c.dispatchMs<=5000&&c.drainedMs-c.dispatchMs<=5000,"CLI full spawn/exit/drain deadline exceeded");}
export async function teardownAll(primary:unknown,resources:{name:string;close:()=>Promise<void>}[],failures:unknown[]){const errors=proofErrors(()=>{});if(primary!==undefined)errors.capture("primary",primary);for(const resource of resources)await errors.attempt(resource.name,resource.close);failures.push(...errors.facts.errors);errors.throwFirst();}
export async function browserRequest(page:Page,path:string,input:unknown,method:string,key:string,originals:unknown[],save:()=>void){
 const body=JSON.stringify(input),record={kind:"browser",path,method,key,body,input:JSON.parse(body),status:null as number|null,text:null as string|null,generation:null as string|null,failure:null as string|null};originals.push(record);save();
 try{const result=await page.evaluate(async({path,body,method,key})=>{let status:number|null=null,text="",generation:string|null=null;try{const response=await fetch("/api/v1"+path,{method,headers:{"Content-Type":"application/json","Idempotency-Key":key},body,signal:AbortSignal.timeout(10000)});status=response.status;generation=response.headers.get("AgentFlow-Generation");const reader=response.body?.getReader(),decoder=new TextDecoder("utf8",{fatal:true});if(reader){try{for(;;){const part=await reader.read();if(part.done)break;text+=decoder.decode(part.value,{stream:true});}text+=decoder.decode();}finally{reader.releaseLock();}}return {status,text,generation,failure:null};}catch(error){return {status,text,generation,failure:String(error)};}},{path,body,method,key});Object.assign(record,result);save();if(record.failure)throw Error(record.failure);assert(record.status!==null&&record.status>=200&&record.status<300,record.text??"no response");const parsed=JSON.parse(record.text!);validateGeneration(record.generation,parsed);return parsed.data;
 }catch(error){record.failure=String(error);save();throw error;}
}
// Browser clocks only bound this wait; elapsed dispatch time is measured by the controller.
export async function currentFrames(e:CurrentExpected & {captureBoundMs?:number}){
 let frames=0,result={frames:0,matched:0,exact:false,visible:false,hitTest:false,observed:[] as Record<string,string|undefined>[]};const start=performance.now();
 while(performance.now()-start<(e.captureBoundMs??5000)){
  await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));const panels=[...document.querySelectorAll<HTMLElement>(`.acceptance-facts[data-task-id="${CSS.escape(e.taskId)}"]`)];const p=panels[0],values=panels.flatMap(p=>[...p.querySelectorAll<HTMLElement>(`[data-current-fact="${e.fact}"]`)]),value=values[0],box=value?.getBoundingClientRect(),url=new URL(location.href);
  const selectedView=[...document.querySelectorAll<HTMLButtonElement>('button[aria-pressed="true"]')].some(button=>button.textContent?.trim()===(e.view==="graph"?"Graph":"List"));
  const route=location.pathname===`/projects/${e.projectId}/workflows`&&url.searchParams.get("workflowId")===e.workflowId&&url.searchParams.get("revisionId")===e.revisionId&&url.searchParams.get("nodeId")===e.nodeId&&(url.searchParams.get("view")==="list"?"list":"graph")===e.view&&selectedView;
  const literal=e.fact==="readiness"?(e.ready?"Prerequisites ready":"Prerequisites blocked"):`Review · Required · ${e.decision==="changes_requested"?"Changes requested":e.decision==="approved"?"Reported approval":"No current reported approval"}`;
  const identity=e.origin!==null&&route&&!!p&&p.dataset.workRevision===String(e.workRevision)&&p.dataset.reworkRound===String(e.reworkRound)&&p.dataset.artifactRef===e.artifactRef&&p.dataset.ready===String(e.ready)&&p.dataset.taskVersion===String(e.version)&&p.dataset.reviewDecision===e.decision&&p.dataset.reviewEventId===e.eventId;
  const matched=identity?values.filter(v=>v.textContent?.trim()===literal).length:0,exact=identity&&panels.length===1&&values.length===1&&matched===1;
  const visible=!!value&&!!box&&value.checkVisibility({checkOpacity:true,checkVisibilityCSS:true})&&box.top>=0&&box.bottom<=innerHeight&&box.left>=0&&box.right<=innerWidth;const hitTest=visible&&!!value&&!!box&&value.contains(document.elementFromPoint(box.x+box.width/2,box.y+box.height/2));frames=exact&&visible&&hitTest?frames+1:0;
  result={frames,matched,exact:!!exact,visible,hitTest,observed:panels.map(p=>({...p.dataset,route:location.href,literal:value?.textContent??undefined,top:box?String(box.top):undefined,bottom:box?String(box.bottom):undefined}))};if(frames===2)return result;
 }return result;
}
export async function dispatchCurrent(receipt:VisibilityReceipt,expected:CurrentExpected[],pages:Page[],dispatch:()=>Promise<unknown>,save:()=>void,captureBoundMs=5000,enforceBudget=true,gate?:MutationGate):Promise<void>{
 if(gate)return gate.run(()=>dispatchCurrent(receipt,expected,pages,dispatch,save,captureBoundMs,enforceBudget),pacing=>{receipt.originals.push({kind:"mutationPermit",scenario:expected[0].scenario,index:expected[0].index,pacing});});
 for(const e of expected){const slot=receipt.expected.findIndex(s=>s.scenario===e.scenario&&s.index===e.index&&s.context===e.context);assert(slot>=0,"undeclared visibility slot");receipt.expected[slot]=e;}save();const start=performance.now();const probes=pages.map((page,context)=>deadline(page.evaluate(currentFrames,{...expected[context],captureBoundMs}).then(facts=>({...expected[context],...facts,elapsedMs:performance.now()-start})),6000,"W02_CURRENT_PROBE_DEADLINE"));const results=await Promise.allSettled([dispatch(),...probes]);for(const r of results.slice(1))if(r.status==="fulfilled")receipt.captures.push(r.value as CurrentCapture);receipt.summary=summarizeCurrent(receipt.expected,receipt.captures);save();for(const r of results)if(r.status==="rejected")throw r.reason;const s=summarizeCurrent(expected,receipt.captures.filter(c=>c.index===expected[0].index));assert(!s.missing&&!s.unconfirmed&&!s.duplicate&&!s.wrong&&!s.hidden&&(!enforceBudget||!s.late),"current transition not confirmed");
}
